<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Cat FAQ</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #090d14;
        --panel: #121826;
        --panel-strong: #182133;
        --text: #f4f7fb;
        --muted: #b6c2d2;
        --accent: #9dd6ff;
        --accent-strong: #68bdf4;
        --border: rgba(255, 255, 255, 0.12);
        --shadow: rgba(0, 0, 0, 0.38);
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-height: 100vh;
        margin: 0;
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at 20% 10%, rgba(104, 189, 244, 0.22), transparent 28rem),
          radial-gradient(circle at 80% 0%, rgba(157, 214, 255, 0.12), transparent 24rem),
          linear-gradient(135deg, #080b11 0%, var(--bg) 45%, #0d111d 100%);
      }

      .app-shell {
        width: min(960px, calc(100% - 32px));
        margin: 0 auto;
        padding: 64px 0;
      }

      .hero {
        margin-bottom: 28px;
        padding: 36px;
        border: 1px solid var(--border);
        border-radius: 28px;
        background: linear-gradient(145deg, rgba(18, 24, 38, 0.92), rgba(24, 33, 51, 0.72));
        box-shadow: 0 24px 80px var(--shadow);
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 10px;
        margin: 0 0 14px;
        color: var(--accent);
        font-size: 0.82rem;
        font-weight: 700;
        letter-spacing: 0.14em;
        text-transform: uppercase;
      }

      .eyebrow::before {
        content: "";
        width: 10px;
        height: 10px;
        border-radius: 50%;
        background: var(--accent-strong);
        box-shadow: 0 0 20px var(--accent-strong);
      }

      h1 {
        max-width: 780px;
        margin: 0;
        font-size: clamp(2.4rem, 7vw, 5rem);
        line-height: 0.95;
        letter-spacing: -0.07em;
      }

      .intro {
        max-width: 680px;
        margin: 18px 0 0;
        color: var(--muted);
        font-size: 1.08rem;
        line-height: 1.7;
      }

      .details {
        display: grid;
        gap: 16px;
      }

      .example {
        overflow: hidden;
        border: 1px solid var(--border);
        border-radius: 22px;
        background: rgba(18, 24, 38, 0.82);
        box-shadow: 0 18px 50px rgba(0, 0, 0, 0.24);
      }

      .question-button {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 24px;
        width: 100%;
        padding: 24px;
        border: 0;
        color: inherit;
        background: transparent;
        font: inherit;
        text-align: left;
        cursor: pointer;
      }

      .question-button:hover,
      .question-button:focus-visible {
        background: rgba(157, 214, 255, 0.08);
      }

      .question-button:focus-visible {
        outline: 3px solid var(--accent);
        outline-offset: -3px;
      }

      .question-text {
        font-size: 1.1rem;
        font-weight: 750;
        letter-spacing: -0.02em;
      }

      .toggle-icon {
        display: inline-grid;
        flex: 0 0 38px;
        width: 38px;
        height: 38px;
        place-items: center;
        border: 1px solid rgba(157, 214, 255, 0.35);
        border-radius: 999px;
        color: var(--accent);
        background: rgba(157, 214, 255, 0.09);
        transition: transform 180ms ease;
      }

      .question-button[aria-expanded="true"] .toggle-icon {
        transform: rotate(45deg);
      }

      .answer {
        padding: 0 24px 24px;
        color: var(--muted);
        font-size: 1rem;
        line-height: 1.7;
      }

      .answer p {
        margin: 0;
        padding-top: 2px;
      }

      @media (max-width: 640px) {
        .app-shell {
          width: min(100% - 20px, 960px);
          padding: 28px 0;
        }

        .hero {
          padding: 24px;
          border-radius: 22px;
        }

        .question-button {
          padding: 20px;
        }

        .answer {
          padding: 0 20px 20px;
        }
      }
    </style>
  </head>
  <body>
    <main id="root" class="app-shell"></main>

    <script>
      const faqs = [
        {
          question: "Why do cats purr?",
          answer:
            "Cats often purr when they feel calm or affectionate, but purring can also be self-soothing. Some cats purr when they are stressed, recovering, or asking for attention."
        },
        {
          question: "How much sleep do cats need?",
          answer:
            "Most adult cats sleep between 12 and 16 hours a day. Kittens and senior cats may sleep even longer because growth, play, and aging all require extra rest."
        },
        {
          question: "Why do cats knead blankets or people?",
          answer:
            "Kneading is a comforting behavior that starts in kittenhood. Adult cats may knead soft surfaces when they feel safe, content, or ready to settle down."
        },
        {
          question: "Should cats drink milk?",
          answer:
            "Many adult cats are lactose intolerant, so cow's milk can upset their stomach. Fresh water is the best daily drink, and cat-safe treats are better for special occasions."
        },
        {
          question: "How can I tell if a cat is happy?",
          answer:
            "Relaxed posture, slow blinking, upright tails, gentle head bumps, and playful curiosity are common happy-cat signals. Every cat is different, so watch for the behaviors your cat repeats when comfortable."
        }
      ];

      function Header() {
        return `
          <section class="hero" aria-labelledby="page-title">
            <p class="eyebrow">Cat care basics</p>
            <h1 id="page-title">Frequently asked questions about cats</h1>
            <p class="intro">
              Quick, practical answers for understanding feline habits, comfort,
              and everyday care.
            </p>
          </section>
        `;
      }

      function FAQItem(item, index, isOpen) {
        const answerId = `answer-${index}`;
        const buttonId = `question-${index}`;

        return `
          <div class="example">
            <button
              id="${buttonId}"
              class="question-button"
              type="button"
              aria-expanded="${isOpen}"
              aria-controls="${answerId}"
              data-index="${index}"
            >
              <span class="question-text">${item.question}</span>
              <span class="toggle-icon" aria-hidden="true">+</span>
            </button>
            <div
              id="${answerId}"
              class="answer"
              role="region"
              aria-labelledby="${buttonId}"
              ${isOpen ? "" : "hidden"}
            >
              <p>${item.answer}</p>
            </div>
          </div>
        `;
      }

      function FAQList(items, openItems) {
        return `
          <section class="details" aria-label="Cat FAQ">
            ${items.map((item, index) => FAQItem(item, index, openItems.has(index))).join("")}
          </section>
        `;
      }

      function App() {
        const openItems = new Set();
        const root = document.querySelector("#root");

        function render() {
          root.innerHTML = Header() + FAQList(faqs, openItems);

          root.querySelectorAll(".question-button").forEach((button) => {
            button.addEventListener("click", () => {
              const index = Number(button.dataset.index);

              if (openItems.has(index)) {
                openItems.delete(index);
              } else {
                openItems.add(index);
              }

              render();
              root.querySelector(`[data-index="${index}"]`).focus();
            });
          });
        }

        render();
      }

      App();
    </script>
  </body>
</html>
